final class ScriptSandbox {
    static String evaluate(String script,Map<String,Object> message){if(script.length()>65536)throw new IllegalArgumentException("Script exceeds 64 KiB");long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);ContextFactory factory=new ContextFactory(){protected Context makeContext(){Context c=super.makeContext();c.setOptimizationLevel(-1);c.setInstructionObserverThreshold(10000);return c;}protected void observeInstructionCount(Context c,int count){if(System.nanoTime()>deadline)throw new Error("Script instruction deadline");}};
        return factory.call(cx->{cx.setClassShutter(name->false);Scriptable scope=cx.initSafeStandardObjects();for(String key:List.of("Packages","java","javax","org","com","JavaAdapter","getClass","load","readFile","require","importClass","importPackage"))ScriptableObject.deleteProperty(scope,key);String payload=Json.write(message);String code="(function(){'use strict';const message=JSON.parse("+VulnApp.json(payload)+");const result=(function(message){"+script+"\n})(message);return JSON.stringify(result || []);})()";String result=Context.toString(cx.evaluateString(scope,code,"vuln-script",1,null));if(result.length()>1024*1024)throw new IllegalArgumentException("Script output exceeds 1 MiB");return result;});}
    static List<WorkbenchCore.Finding> run(String script,VulnApp.Exchange e)throws Exception{if(e.request().length+e.response().length>2*1024*1024)throw new IOException("Script message limit: 2 MiB");Map<String,Object> message=Map.of("method",e.method(),"url",e.url(),"request",new String(e.request(),VulnApp.WIRE),"response",new String(e.response(),VulnApp.WIRE));Path folder=Files.createTempDirectory("vuln-script-");Path input=folder.resolve("input.json"),out=folder.resolve("output.json"),error=folder.resolve("error.txt");try{Files.writeString(input,Json.write(Map.of("script",script,"message",message)));String java=Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString();Process process=new ProcessBuilder(java,"-Xmx96m","-XX:MaxMetaspaceSize=64m","-cp",System.getProperty("java.class.path"),"ScriptSandbox",input.toString()).redirectOutput(out.toFile()).redirectError(error.toFile()).start();if(!process.waitFor(5,TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor(2,TimeUnit.SECONDS);throw new IOException("Script exceeded worker timeout");}if(process.exitValue()!=0)throw new IOException("Script failed: "+Files.readString(error).substring(0,(int)Math.min(2048,Files.size(error))));if(Files.size(out)>1024*1024)throw new IOException("Script output limit");Object value=Json.parse(Files.readString(out));if(!(value instanceof List<?> list))throw new IOException("Script must return an array");if(list.size()>100)throw new IOException("Script finding limit");List<WorkbenchCore.Finding> findings=new ArrayList<>();for(Object entry:list){Map<String,Object> row=Json.object(entry);findings.add(new WorkbenchCore.Finding(String.valueOf(row.getOrDefault("severity","Info")),String.valueOf(row.getOrDefault("title","Script finding")),e.url(),String.valueOf(row.getOrDefault("evidence","")),"Script evidence; review required"));}return findings;}finally{for(Path p:List.of(input,out,error))Files.deleteIfExists(p);Files.deleteIfExists(folder);}}
    public static void main(String[] args)throws Exception{Map<String,Object> input=Json.object(Json.parse(Files.readString(Path.of(args[0]))));System.out.print(evaluate(String.valueOf(input.get("script")),Json.object(input.get("message"))));}
}
